const helper = `int checkNextToken(const Parser *parser, const char *type)
{
    size_t remaining = parser->tokens->size - parser->pos;

    if (remaining < 2)
    {
        return 0;
    }

    return strcmp(parser->tokens->data[parser->pos + 1].type, type) == 0;
}
`;
const params = `int parseFuncRParams(Parser *parser)
{
    size_t start = parser->pos;

    if (!parseExp(parser))
    {
        parser->pos = start;
        return 0;
    }

    while (matchToken(parser, "COMMA"))
    {
        if (!parseExp(parser))
        {
            parser->pos = start;
            return 0;
        }
    }

    return 1;
}
`;
const unary = `int parseUnaryExp(Parser *parser)
{
    size_t start = parser->pos;

    if (parseUnaryOp(parser))
    {
        if (parseUnaryExp(parser))
        {
            return 1;
        }

        parser->pos = start;
        return 0;
    }

    if (checkToken(parser, "IDENFR") &&
        checkNextToken(parser, "LPARENT"))
    {
        advanceToken(parser);
        advanceToken(parser);

        if (!checkToken(parser, "RPARENT") &&
            !parseFuncRParams(parser))
        {
            parser->pos = start;
            return 0;
        }

        if (!matchToken(parser, "RPARENT"))
        {
            parser->pos = start;
            return 0;
        }

        return 1;
    }

    if (checkToken(parser, "LPARENT") &&
        (checkNextToken(parser, "INTTK") ||
         checkNextToken(parser, "CHARTK")))
    {
        advanceToken(parser);

        if (!parseBType(parser) ||
            !matchToken(parser, "RPARENT") ||
            !parseUnaryExp(parser))
        {
            parser->pos = start;
            return 0;
        }

        return 1;
    }

    return parsePrimaryExp(parser);
}
`;
