const stmt = `int parseStmt(Parser *parser)
{
    size_t start = parser->pos;

    // 嵌套语句块
    if (checkToken(parser, "LBRACE"))
    {
        return parseBlock(parser);
    }

    // return [Exp] ';'
    if (matchToken(parser, "RETURNTK"))
    {
        if (!checkToken(parser, "SEMICN") &&
            !parseExp(parser))
        {
            parser->pos = start;
            return 0;
        }

        if (!matchToken(parser, "SEMICN"))
        {
            parser->pos = start;
            return 0;
        }

        return 1;
    }

    // 空语句
    if (matchToken(parser, "SEMICN"))
    {
        return 1;
    }

    // 尝试赋值语句
    if (parseLVal(parser))
    {
        if (matchToken(parser, "ASSIGN"))
        {
            if (!parseExp(parser) ||
                !matchToken(parser, "SEMICN"))
            {
                parser->pos = start;
                return 0;
            }

            return 1;
        }
    }

    // 没有识别为赋值，重新按表达式语句读取
    parser->pos = start;

    if (!parseExp(parser) ||
        !matchToken(parser, "SEMICN"))
    {
        parser->pos = start;
        return 0;
    }

    return 1;
}
`;
