const harness=String.raw`#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define main parser_program_main
#include "parser_candidate.c"
#undef main
#undef malloc
#undef realloc
#undef free

static long liveBlocks = 0;
static long allocationBudget = -1;
static long allocationCalls = 0;

void *treeTestMalloc(size_t size)
{
    allocationCalls++;
    if (allocationBudget == 0) return NULL;
    if (allocationBudget > 0) allocationBudget--;
    void *value = malloc(size);
    if (value != NULL) liveBlocks++;
    return value;
}
void *treeTestRealloc(void *pointer, size_t size)
{
    allocationCalls++;
    if (allocationBudget == 0) return NULL;
    if (allocationBudget > 0) allocationBudget--;
    int wasNull = pointer == NULL;
    void *value = realloc(pointer, size);
    if (value != NULL && wasNull) liveBlocks++;
    return value;
}
void treeTestFree(void *pointer)
{
    if (pointer != NULL) { assert(liveBlocks > 0); liveBlocks--; }
    free(pointer);
}

static size_t terminalCursor = 0;
static size_t treeNodeCount = 0;
static void dumpTree(FILE *out, const SyntaxNode *node, const TokenList *tokens)
{
    assert(node != NULL);
    treeNodeCount++;
    assert(node->childCount <= node->childCapacity);
    if (node->kind == NODE_TERMINAL)
    {
        assert(node->childCount == 0);
        assert(terminalCursor < tokens->size);
        assert(node->token == &tokens->data[terminalCursor++]);
        assert(strcmp(node->name, node->token->type) == 0);
    }
    else
    {
        assert(node->kind == NODE_NONTERMINAL && node->token == NULL);
        assert(node->childCount > 0);
    }
    assert(fprintf(out, "{\"name\":\"%s\",\"terminal\":%d,\"children\":[",
                   node->name, node->kind == NODE_TERMINAL) >= 0);
    for (size_t i = 0; i < node->childCount; i++)
    {
        if (i != 0) assert(fputc(',', out) != EOF);
        dumpTree(out, node->children[i], tokens);
    }
    assert(fputs("]}", out) >= 0);
}

int main(int argc, char **argv)
{
    FILE *input = fopen("lexer.txt", "r");
    assert(input != NULL);
    TokenList tokens;
    initTokenList(&tokens);
    char line[8192];
    while (fgets(line, sizeof(line), input) != NULL)
    {
        line[strcspn(line, "\r\n")] = '\0';
        char *space = strchr(line, ' ');
        assert(space != NULL);
        *space = '\0';
        char *type = malloc(strlen(line) + 1);
        assert(type != NULL);
        strcpy(type, line);
        assert(addToken(&tokens, type, space + 1, 1));
    }
    assert(!ferror(input) && fclose(input) == 0);
    Parser parser = {0};
    parser.tokens = &tokens;
    allocationCalls = 0;
    int result = parseCompUnit(&parser);
    long fullAllocations = allocationCalls;
    int invalid = argc > 1 && strcmp(argv[1], "invalid") == 0;
    if (invalid)
    {
        assert(!result && !parser.memoryError);
        assert(parser.pos == 0 && parser.nodeCount == 0);
    }
    else
    {
        assert(result && !parser.memoryError && parser.pos == tokens.size);
        assert(parser.nodeCount == 1 && strcmp(parser.nodes[0]->name, "CompUnit") == 0);
        FILE *out = fopen("tree.json", "w");
        assert(out != NULL);
        dumpTree(out, parser.nodes[0], &tokens);
        assert(terminalCursor == tokens.size && fclose(out) == 0);
    }
    freeParserTrees(&parser);
    assert(liveBlocks == 0);

    long budgetsTested = 0;
    if (argc > 1 && strcmp(argv[1], "fault") == 0)
    {
        for (long budget = 0; budget < fullAllocations; budget++)
        {
            Parser attempt = {0};
            attempt.tokens = &tokens;
            allocationBudget = budget;
            allocationCalls = 0;
            assert(!parseCompUnit(&attempt));
            assert(attempt.memoryError && attempt.pos == 0 && attempt.nodeCount == 0);
            freeParserTrees(&attempt);
            assert(liveBlocks == 0);
            allocationBudget = -1;
            budgetsTested++;
        }
    }

    Token numbers[] = {{"INTCON","2",1},{"INTCON","3",1}};
    TokenList numberList = {numbers, 2, 2};
    Parser prefix = {0};
    prefix.tokens = &numberList;
    ParserMark empty = markParser(&prefix);
    assert(parseNumber(&prefix));
    ParserMark keep = markParser(&prefix);
    SyntaxNode *first = prefix.nodes[0];
    assert(parseNumber(&prefix));
    rollbackParser(&prefix, keep);
    assert(prefix.pos == 1 && prefix.nodeCount == 1 && prefix.nodes[0] == first);
    assert(first->children[0]->token == &numbers[0]);
    rollbackParser(&prefix, empty);
    assert(prefix.pos == 0 && prefix.nodeCount == 0 && parseNumber(&prefix));
    freeParserTrees(&prefix);
    assert(liveBlocks == 0);

    for (size_t i = 0; i < tokens.size; i++) free((void *)tokens.data[i].type);
    freeTokenList(&tokens);
    printf("tree_nodes=%lu fault_budgets=%ld\n",
           (unsigned long)treeNodeCount, budgetsTested);
    return 0;
}
