const validate=String.raw`def validate_tree(node, seen):
    name=node['name']
    children=node['children']
    if node['terminal']:
        assert not children
        return
    seen.add(name)
    for child in children:
        validate_tree(child,seen)
    c=[child['name'] for child in children]
    def exact(wanted):
        assert c==wanted,(name,c,wanted)
    def series(items, item):
        assert items and len(items)%2==1,(name,items)
        assert items[::2]==[item]*((len(items)+1)//2),(name,items)
        assert items[1::2]==['COMMA']*(len(items)//2),(name,items)
    atoms={'BType':['INTTK','CHARTK'],'Number':['INTCON','CHARCON'],
           'UnaryOp':['PLUS','MINU','NOT'],'FuncType':['VOIDTK','INTTK','CHARTK']}
    binary={'MulExp':('UnaryExp',['MULT','DIV','MOD']),
            'AddExp':('MulExp',['PLUS','MINU']),
            'RelExp':('AddExp',['LSS','GRE','LEQ','GEQ']),
            'EqExp':('RelExp',['EQL','NEQ']),
            'LAndExp':('EqExp',['AND']),'LOrExp':('LAndExp',['OR'])}
    if name in atoms:
        assert len(c)==1 and c[0] in atoms[name],(name,c)
    elif name in binary:
        lower,ops=binary[name]
        assert c==[lower] or (len(c)==3 and c[0]==name and c[1] in ops and c[2]==lower),(name,c)
    elif name in ['Exp','ConstExp','Cond']:
        exact([{'Exp':'AddExp','ConstExp':'AddExp','Cond':'LOrExp'}[name]])
    elif name=='PrimaryExp':
        assert c in [['LVal'],['Number'],['LPARENT','Exp','RPARENT']],c
    elif name=='UnaryExp':
        assert (c in [['PrimaryExp'],['UnaryOp','UnaryExp'],['LPARENT','BType','RPARENT','UnaryExp'],
                      ['IDENFR','LPARENT','RPARENT'],
                      ['IDENFR','LPARENT','FuncRParams','RPARENT']]),c
    elif name=='LVal':
        assert c in [['IDENFR'],['IDENFR','LBRACK','Exp','RBRACK']],c
    elif name in ['FuncRParams','FuncFParams']:
        series(c, 'Exp' if name=='FuncRParams' else 'FuncFParam')
    elif name in ['ConstInitVal','InitVal']:
        expr='ConstExp' if name=='ConstInitVal' else 'Exp'
        if c in [[expr],['STRCON']]: pass
        else:
            assert c[0]=='LBRACE' and c[-1]=='RBRACE',(name,c)
            if c[1:-1]: series(c[1:-1],expr)
    elif name in ['ConstDef','VarDef']:
        assert c[0]=='IDENFR',(name,c)
        i=1
        if i<len(c) and c[i]=='LBRACK':
            assert c[i:i+3]==['LBRACK','ConstExp','RBRACK'],(name,c)
            i+=3
        if name=='ConstDef': assert c[i:]==['ASSIGN','ConstInitVal'],c
        else: assert c[i:] in [[],['ASSIGN','InitVal']],c
    elif name in ['ConstDecl','VarDecl']:
        i=0
        if name=='ConstDecl':
            assert c[0]=='CONSTTK',c
            i=1
        elif c[0]=='STATICTK': i=1
        assert c[i]=='BType' and c[-1]=='SEMICN',(name,c)
        series(c[i+1:-1], 'ConstDef' if name=='ConstDecl' else 'VarDef')
    elif name=='Decl':
        assert c in [['ConstDecl'],['VarDecl']],c
    elif name=='FuncFParam':
        assert c in [['BType','IDENFR'],['BType','IDENFR','LBRACK','RBRACK']],c
    elif name=='Stmt':
        if c[0]=='Block': exact(['Block'])
        elif c[0]=='IFTK':
            assert c[:5]==['IFTK','LPARENT','Cond','RPARENT','Stmt'],c
            assert c[5:] in [[],['ELSETK','Stmt']],c
        elif c[0]=='WHILETK': exact(['WHILETK','LPARENT','Cond','RPARENT','Stmt'])
        elif c[0] in ['BREAKTK','CONTINUETK']: exact([c[0],'SEMICN'])
        elif c[0]=='RETURNTK':
            assert c in [['RETURNTK','SEMICN'],['RETURNTK','Exp','SEMICN']],c
        elif c[0]=='LVal': exact(['LVal','ASSIGN','Exp','SEMICN'])
        elif c[0]=='Exp': exact(['Exp','SEMICN'])
        elif c[0]=='SEMICN': exact(['SEMICN'])
        elif c[0]=='PRINTFTK':
            assert c[:3]==['PRINTFTK','LPARENT','STRCON'] and c[-2:]==['RPARENT','SEMICN'],c
            mid=c[3:-2]
            assert len(mid)%2==0 and mid[::2]==['COMMA']*(len(mid)//2) and mid[1::2]==['Exp']*(len(mid)//2),c
        elif c[0]=='SWITCHTK':
            assert c[:5]==['SWITCHTK','LPARENT','Exp','RPARENT','LBRACE'] and c[-1]=='RBRACE',c
            assert all(x=='CaseStmt' for x in c[5:-1]),c
        else: raise AssertionError(('Stmt',c))
    elif name=='CaseStmt':
        i=3 if c[0]=='CASETK' else 2
        assert c[:i]==(['CASETK','Number','COLON'] if i==3 else ['DEFAULTTK','COLON']),c
        assert all(x=='Stmt' for x in c[i:]),c
    elif name=='BlockItem': assert c in [['Decl'],['Stmt']],c
    elif name=='Block':
        assert c[0]=='LBRACE' and c[-1]=='RBRACE' and all(x=='BlockItem' for x in c[1:-1]),c
    elif name=='FuncDef':
        assert c[:3]==['FuncType','IDENFR','LPARENT'] and c[-2:]==['RPARENT','Block'],c
        assert c[3:-2] in [[],['FuncFParams']],c
    elif name=='MainFuncDef': exact(['INTTK','MAINTK','LPARENT','RPARENT','Block'])
    elif name=='CompUnit':
        i=0
        while i<len(c) and c[i]=='Decl': i+=1
        while i<len(c) and c[i]=='FuncDef': i+=1
        assert c[i:]==['MainFuncDef'],c
    else: raise AssertionError(('unknown node',name))
